from pydantic import BaseModel

app = FastAPI()

class UserLogin(BaseModel):
    username: str
    password: str
@app.get("/")
async def root():
    return {"message": "Hello World"}

@app.post("/login")
async def say_hello(data: UserLogin):
    return {"message": f"Hello World"}
```

